contract InvMutTest {
    C c;
    address deployer;

    constructor(C _c) { c = _c; deployer = msg.sender; }

    // single public test function taking inputs: callerIsOwner decides who calls withdrawAll;
    // recipient is where funds should go; fundAmount is sent to c before withdraw.
    function run(bool callerIsOwner, address payable recipient, uint256 fundAmount) public payable {
        require(address(this).balance >= fundAmount);

        // Read initial observable values
        address ownerBefore = c.owner();
        uint256 balanceBefore = address(c).balance;

        // Fund the contract c by sending Ether from this test contract
        if (fundAmount > 0) {
            // ensure we actually send Ether to c
            (bool s, ) = address(c).call{value: fundAmount}("");
            require(s);
        }

        uint256 balanceAfterFunding = address(c).balance;

        // Decide who will invoke withdrawAll: owner must be msg.sender of the call.
        // If callerIsOwner is true, we attempt to call as the owner by ensuring ownerBefore == address(this).
        // Since the test contract cannot change c.owner(), this only makes sense if deployer set owner to this test contract.
        // We allow both possibilities: if callerIsOwner is requested but test contract is not the owner, we will still perform the call and observe it reverts.

        bool reverted;
        // Perform the withdrawAll call from this contract (InvMutTest). The checker runs run() as one transaction where this contract is msg.sender to c.
        try c.withdrawAll(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 balanceAfter = address(c).balance;
        uint256 recipientBalanceAfter = address(recipient).balance;

        // General rule asserting correct behavior for both owner and non-owner caller cases.
        // - If this contract is the owner (ownerBefore == address(this)) then withdrawAll must not revert and it must transfer the entire contract balance to recipient.
        // - If this contract is not the owner then withdrawAll must revert and the contract balance must be unchanged by the call.
        assert(
            (ownerBefore == address(this) && reverted == false && balanceAfter == 0 && balanceAfterFunding == address(recipient).balance - recipientBalanceAfter + balanceAfter) ||
            (ownerBefore != address(this) && reverted == true && balanceAfter == balanceAfterFunding)
        );
    }

    // Allow receiving Ether when c sends funds to this contract if recipient is this contract
    receive() external payable {}
}

